        mock_get_insight.return_value = (True, {
            'data': {
                'title': 'Sample PDF',
                'content': 'This is a sample PDF content for testing purposes.',
                'footer': 'Footer information'
            }
        })
        response = self.client.get(
            reverse('partners_api:pca_pdf', args=[self.agreement.pk]),
            data=params
        )
